   708  // <abi-tags> ::= <abi-tag> [<abi-tags>]
   709  static bool ParseAbiTags(State *state) {
   710    State copy = *state;
   711    DisableAppend(state);
   712    if (OneOrMore(ParseAbiTag, state)) {
   713      RestoreAppend(state, copy.append);
   714      return true;
   715    }
   716    *state = copy;
   717    return false;
   718  }
